+function isNonEmptyString(value: unknown): value is string {
+    return typeof value === "string" && value.trim().length > 0;
+}
+
+export function parseTravelPlanResponse(responseText: string): TravelPlan | null {
+    const trimmedText = responseText.trim();
+    const jsonText = trimmedText.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i)?.[1] ?? trimmedText;
+
+    try {
+        const value: unknown = JSON.parse(jsonText);
+        if (typeof value !== "object" || value === null) return null;
+
+        const plan = value as Record<string, unknown>;
+        if (!isNonEmptyString(plan.intro) || !Array.isArray(plan.days) || plan.days.length !== 3) return null;
+        if (!plan.days.every((day) => {
+            if (typeof day !== "object" || day === null) return false;
+            const item = day as Record<string, unknown>;
+            return typeof item.day === "number" && Number.isFinite(item.day)
+                && isNonEmptyString(item.title)
+                && Array.isArray(item.activities) && item.activities.length > 0
+                && item.activities.every(isNonEmptyString);
+        })) return null;
+
+        if (typeof plan.hiddenGem !== "object" || plan.hiddenGem === null
+            || typeof plan.localFood !== "object" || plan.localFood === null) return null;
+        const hiddenGem = plan.hiddenGem as Record<string, unknown>;
+        const localFood = plan.localFood as Record<string, unknown>;
+        if (!isNonEmptyString(hiddenGem.title) || !isNonEmptyString(hiddenGem.description)
+            || !isNonEmptyString(localFood.dish) || !isNonEmptyString(localFood.description)) return null;
+
+        return value as TravelPlan;
+    } catch {
+        return null;
+    }
+}
